<script setup lang="ts">
import{computed,ref}from'vue';import{onLoad}from'@dcloudio/uni-app';import AppHeader from'../../components/AppHeader.vue';import StatusNotice from'../../components/StatusNotice.vue';import{api,apiRuntime}from'../../api/client';import{toOrderProjection,type ProjectProjection}from'../../api/project-contract';import{fromProjection}from'../../domain/price-snapshot';import{validateOrderSnapshot}from'../../domain/snapshot-flow';import{getOrCreateCommand}from'../../domain/command-identity';import type{OrderProjection}from'../../domain/types'
const p=ref<OrderProjection|null>(null),core=ref<ProjectProjection|null>(null),orderRef=ref(''),error=ref(''),loading=ref(false);const ready=computed(()=>validateOrderSnapshot(uni,orderRef.value,p.value?fromProjection(p.value):null));const canTopup=computed(()=>ready.value&&!!core.value?.allowedActions.some(a=>a.actionCode==='REQUEST_MOCK_TOPUP'))
async function refresh(){if(!orderRef.value)return;try{if(apiRuntime.mode==='PROJECT_MOCK_API'){core.value=await api.getCoreProjection(orderRef.value);p.value=toOrderProjection(core.value)}else p.value=await api.getProjection(orderRef.value)}catch{error.value='投影读取失败，不得推进。'}}
async function completeTopup(){if(!canTopup.value||!core.value)return;loading.value=true;try{const c=getOrCreateCommand(uni,`mock-topup:${orderRef.value}`);core.value=await api.completeMockTopup(orderRef.value,c.commandId,c.idempotencyKey,core.value.projectionVersion,core.value.aggregateVersion,'CONFIRMED');p.value=toOrderProjection(core.value)}catch{error.value='Mock充值结果未确认；只允许原订单查询。'}finally{loading.value=false}}
onLoad(q=>{orderRef.value=typeof q?.orderRef==='string'?decodeURIComponent(q.orderRef):'';refresh()})
</script>
<template><view class="page"><AppHeader left="← 订单" @left="uni.navigateBack()"/><view class="content"><view class="heading" role="heading" aria-level="1">充值进度</view><StatusNotice v-if="error" tone="risk" title="读取错误">{{error}}</StatusNotice><StatusNotice v-if="p&&!ready" tone="risk" title="STALE / 冻结快照不一致">业务动作资格为 0。</StatusNotice><view class="card"><view class="kv"><text>订单状态</text><text>{{core?.orderState||p?.stateCode||'UNKNOWN'}}</text></view><view class="kv"><text>支付/U/D</text><text>{{core?.facts.payment||'UNKNOWN'}} / {{core?.facts.upstreamDebit||'UNKNOWN'}} / {{core?.facts.delivery||'UNKNOWN'}}</text></view><view class="kv"><text>双版本</text><text>{{core?.projectionVersion??'—'}} / {{core?.aggregateVersion??'—'}}</text></view></view><view class="card"><text class="card-title">B1</text><text class="copy">UNKNOWN 仅沿原订单查询，不生成新语义键或自动真实充值。</text></view></view><view class="action"><button v-if="apiRuntime.mode==='PROJECT_MOCK_API'" class="primary" :disabled="!canTopup||loading" @click="completeTopup">完成 Mock 充值</button><button class="secondary" @click="refresh">只读刷新投影</button></view></view></template><style src="../../styles/shared.css"></style>
